import static java.nio.charset.StandardCharsets.UTF_8;
import org.springframework.http.*;
import org.springframework.http.converter.*;
import org.springframework.http.converter.json.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.*;
import static org.springframework.test.web.servlet
        .request.MockMvcRequestBuilders.*;

// 業務例外:「タスクが無い」
class TaskNotFoundException extends RuntimeException {
    TaskNotFoundException(long id) {
        super("タスク " + id + " は見つかりません");
    }
}

record Task(long id, String title) {}

@RestController
@RequestMapping("/api/tasks")
class TaskController {
    private final Map<Long, Task> store = Map.of(1L, new Task(1, "請求書を送る"));

    @GetMapping("/{id}")
    Task get(@PathVariable long id) {
        Task t = store.get(id);
        if (t == null) {
            throw new TaskNotFoundException(id);   // 404 を作らず、投げるだけ
        }
        return t;
    }
}

// 全 Controller 共通の例外ハンドラ
@RestControllerAdvice
class ApiExceptionHandler {
    @ExceptionHandler(TaskNotFoundException.class)
    ProblemDetail handleNotFound(TaskNotFoundException ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
                HttpStatus.NOT_FOUND, ex.getMessage());
        pd.setTitle("タスクが見つかりません");
        return pd;
    }
}

MockMvc build(boolean withAdvice) {
    var b = MockMvcBuilders.standaloneSetup(new TaskController());
    if (withAdvice) {
        b.setControllerAdvice(new ApiExceptionHandler());
    }
    return b.setMessageConverters(new StringHttpMessageConverter(UTF_8),
                                  new MappingJackson2HttpMessageConverter())
            .defaultResponseCharacterEncoding(UTF_8)
            .build();
}

long id = 99;

System.out.println("■ ハンドラなし");
try {
    var r = build(false).perform(get("/api/tasks/" + id))
            .andReturn().getResponse();
    System.out.println("  " + r.getStatus() + " " + r.getContentAsString());
} catch (Exception e) {
    // Spring Boot なら、ここから先は Tomcat → /error で 500 になる
    Throwable c = e.getCause();
    System.out.println("  例外が Controller の外へ漏れた: "
        + c.getClass().getSimpleName() + ": " + c.getMessage());
}

System.out.println("■ ハンドラあり");
var res = build(true).perform(get("/api/tasks/" + id))
        .andReturn().getResponse();
System.out.println("  " + res.getStatus() + " " + res.getContentType());
System.out.println("  " + res.getContentAsString());

