// ダメな例:Exception をまるごと 500 にしてしまう
@RestControllerAdvice
class CatchAllAdvice {
    @ExceptionHandler(Exception.class)
    ProblemDetail handle(Exception ex) {
        return ProblemDetail.forStatusAndDetail(
                HttpStatus.INTERNAL_SERVER_ERROR, "システムエラーが発生しました");
    }
}

// 良い例:Spring MVC 自身の例外は親クラスが正しいステータスにする
@RestControllerAdvice
class BetterAdvice extends ResponseEntityExceptionHandler {
    @ExceptionHandler(Exception.class)
    ProblemDetail handle(Exception ex) {
        return ProblemDetail.forStatusAndDetail(
                HttpStatus.INTERNAL_SERVER_ERROR, "システムエラーが発生しました");
    }
}

void tryAll(Object advice) throws Exception {
    MockMvc mvc = MockMvcBuilders.standaloneSetup(new TaskController())
            .setControllerAdvice(advice)
            .setMessageConverters(new StringHttpMessageConverter(UTF_8),
                                  new MappingJackson2HttpMessageConverter())
            .defaultResponseCharacterEncoding(UTF_8)
            .build();
    System.out.println("■ " + advice.getClass().getSimpleName());
    var r1 = mvc.perform(get("/api/tasks")).andReturn().getResponse();
    System.out.println("  GET(未対応のメソッド)    → " + r1.getStatus());
    var r2 = mvc.perform(post("/api/tasks").content("title=x"))
            .andReturn().getResponse();
    System.out.println("  POST(Content-Type なし) → " + r2.getStatus());
    var r3 = mvc.perform(post("/api/tasks")
            .contentType(MediaType.APPLICATION_JSON)
            .content("{\"id\":1,")).andReturn().getResponse();
    System.out.println("  POST(壊れた JSON)       → " + r3.getStatus());
    System.out.println("    " + r3.getContentAsString());
}

tryAll(new CatchAllAdvice());
tryAll(new BetterAdvice());

